class Job(AmplifyJobModelMixin, PrimaryBoto3Model):
    """
    Describes an execution job for an Amplify app.
    """

    manager_class: ClassVar[ModelType[Boto3ModelManager]] = JobManager

    summary: JobSummary
    """
    Describes the summary for an execution job for an Amplify app.
    """

    steps: "builtins.list[AmplifyStep]"
    """
    The execution steps for an execution job, for an Amplify app.
    """
    appId: str | None = None
    """
    Owning app id.

    Copied from the get or list request.
    """

    branchName: str | None = None
    """
    Owning branch name.

    Copied from the get or list request.
    """

    @property
    def pk(self) -> OrderedDict[str, Any]:
        """
        App id, branch name, and job id.

        Delete needs all three.
        """
        return OrderedDict(
            {
                "appId": self.appId,
                "branchName": self.branchName,
                "jobId": self.summary.jobId,
            }
        )


